    "content": "新华社华盛顿11月5日电（记者熊茂伶 徐剑梅）在3日举行的美国中期选举中，民主党从共和党手中夺回国会参众两院控制权。胜选之后，民主党将如何利用国会多数地位，成为外界关注焦点。 分析人士认为，民主党赢得选举并不意味着其受到选民广泛认可，也不代表其具备推动重大政策转向的能力。在国会与白宫分立、2028年总统选举逐渐进入政治议程的背景下，两党争斗将进一步加剧。此外，民主党能否弥合党内建制派与“进步派”的分歧，也将影响其政治前景。 “同行衬托” 媒体和分析人士指出，民主党在中期选举掀起“蓝潮”（蓝色是民主党的代表色），更多…"
