    "content": "第九届中国国际进口博览会期间，高通全球首个符合 3GPP 最新定义的 6G 终端原型机首次走出实验室，在全球大型展会上公开实物展出。该原型机主要用于展示高通在 6G 终端研发、测试验证及产业合作方面的最新进展。 据介绍，本届进博会从上万件展品中遴选出 25 项“黑科技”与“硬科技”展品，高通 6G 终端原型机是通信设备类别中唯一入选的展品，并获得进博局颁布的“硬科技展品”和“全球首展”标识。 作为端到端 6G 原型系统，该原型机用于验证新频谱、宽带宽及关键无线技术的系统级性能，并引入 Giga-MIMO、概率整形和…"
