    "description": "11月5日，智己汽车“NEXT·2028”战略首款全线控大五座旗舰SUV——智己LS8 NEO纯电正式上市，权益价23.98万元起。自预售开启以来，全国门店热度持续走高。作为上汽集团与宁德时代两大行业龙头联手打造的家庭品质旗舰，智己LS8 NEO纯电全系标配全新NEO三电架构、全线控灵蜥底盘、全域物理AI智能三大旗舰科技。",
    "content": "11月5日，智己汽车“NEXT·2028”战略首款全线控大五座旗舰SUV——智己LS8 NEO纯电正式上市，权益价23.98万元起。自预售开启以来，全国门店热度持续走高。作为上汽集团与宁德时代两大行业龙头联手打造的家庭品质旗舰，智己LS8 NEO纯电全系标配全新NEO三电架构、全线控灵蜥底盘、全域物理AI智能三大旗舰科技。"
