    "description": "贵州省铜仁市石阡县独特的地质地貌造就了丰富的地热资源。近年来，石阡县正做大做强“温泉文章”。2025年石阡温泉景区共接待游客85.59万人次，旅游综合收入8199.9万元，受温泉产业带动，2025年石阡县共接待游客520万人次，实现旅游总收入96亿元。 苔茶是石阡的特产。目前，石阡全县投产茶园33.85万亩，2025年实现茶叶总产量2.97万吨，综合产值32.61亿元，茶叶加工企业187家，全县培育茶叶专业合作社、家庭农场等新型经营主体…",
