    "author": "",
    "description": "丰田宣布新一轮组织架构调整，其中最受关注的动作是设立专门的机器人部门，并将该业务定位为“未来业务的关键支柱”。这是丰田首次将机器人业务从生产制造体系中剥离，升级为与电动化、软件业务并列的核心战略事业板块。（财联社）",
    "content": "丰田宣布新一轮组织架构调整，其中最受关注的动作是设立专门的机器人部门，并将该业务定位为“未来业务的关键支柱”。这是丰田首次将机器人业务从生产制造体系中剥离，升级为与电动化、软件业务并列的核心战略事业板块。（财联社）"
