    "author": "",
    "description": "新华社柏林11月5日电（记者赵建通）德国拜仁慕尼黑足球俱乐部5日宣布，与新科金球奖得主、英格兰队队长哈里·凯恩续约至2029年6月30日，较原合同延长两年。 现年33岁的凯恩不久前首获金球奖。他于2023年8月从英超托特纳姆热刺转会至拜仁，迄今已代表球队出战161场正式比赛，攻入156球。 “我在拜仁有家的感觉。”凯恩在俱乐部发布的公告中说。他表示，自己和家人在慕尼黑生活得十分幸福，希望继续随球队赢得更多冠军。 拜仁负责体育事务的董事马…",
    "content": "新华社柏林11月5日电（记者赵建通）德国拜仁慕尼黑足球俱乐部5日宣布，与新科金球奖得主、英格兰队队长哈里·凯恩续约至2029年6月30日，较原合同延长两年。 现年33岁的凯恩不久前首获金球奖。他于2023年8月从英超托特纳姆热刺转会至拜仁，迄今已代表球队出战161场正式比赛，攻入156球。 “我在拜仁有家的感觉。”凯恩在俱乐部发布的公告中说。他表示，自己和家人在慕尼黑生活得十分幸福，希望继续随球队赢得更多冠军。 拜仁负责体育事务的董事马克斯·埃贝尔表示，此次续约为俱乐部未来的阵容规划提供了保障，凯恩将继续在球队建设…"
