    "description": "新华社达卡11月5日电（记者陈冬书）11月1日至5日，中共中央对外联络部部长刘海星率中共代表团访问巴基斯坦、孟加拉国，分别会见巴总理夏巴兹，国防军司令兼陆军参谋长穆尼尔，副总理兼外长达尔，孟总统阿拉姆吉尔，总理塔里克，民族主义党代理总书记里兹维等，在伊斯兰堡出席习近平党建思想交流会、“中国行、兄弟情：中国共产党的巴铁朋友们”交流活动暨巴中治党治国研究中心成立仪式，在达卡出席中孟“政党+”圆桌会暨孟中治党治国研究中心成立仪式、中孟“政党+…",
    "content": "新华社达卡11月5日电（记者陈冬书）11月1日至5日，中共中央对外联络部部长刘海星率中共代表团访问巴基斯坦、孟加拉国，分别会见巴总理夏巴兹，国防军司令兼陆军参谋长穆尼尔，副总理兼外长达尔，孟总统阿拉姆吉尔，总理塔里克，民族主义党代理总书记里兹维等，在伊斯兰堡出席习近平党建思想交流会、“中国行、兄弟情：中国共产党的巴铁朋友们”交流活动暨巴中治党治国研究中心成立仪式，在达卡出席中孟“政党+”圆桌会暨孟中治党治国研究中心成立仪式、中孟“政党+”“点亮未来”民生捐赠活动等，积极宣介中共二十届五中全会精神，就双方共同关心的问…"
