    "description": "新华社香港11月5日电（谢妞）由香港浙江大学教育基金会主办的“2026浙江大学科技创新论坛”5日在港举行。本次论坛以“科技前沿引领·浙港融合创新”为主题，通过科创项目展示和路演，推动科研、产业与资本精准对接。 本次论坛吸引近300位政府、产业、学界及投资界代表出席，60余家“浙大系”校友企业、100余位科技企业家携项目参会，80多家投资机构到场交流。 香港特区政府创新科技及工业局常任秘书长蔡杰铭致辞表示，香港正全速推进“三大创科园区、五…",
    "content": "新华社香港11月5日电（谢妞）由香港浙江大学教育基金会主办的“2026浙江大学科技创新论坛”5日在港举行。本次论坛以“科技前沿引领·浙港融合创新”为主题，通过科创项目展示和路演，推动科研、产业与资本精准对接。 本次论坛吸引近300位政府、产业、学界及投资界代表出席，60余家“浙大系”校友企业、100余位科技企业家携项目参会，80多家投资机构到场交流。 香港特区政府创新科技及工业局常任秘书长蔡杰铭致辞表示，香港正全速推进“三大创科园区、五大研发机构”的创科发展格局，将形成上中下游协同发展，为海内外创科企业提供全链条支…"
