    "content": "新华社南宁11月5日电（记者黄凯莹、彭韵佳）5日，2026全国医保影像AI识图大赛在广西南宁市落下帷幕。大赛由国家医疗保障局、广西壮族自治区政府联合主办，共计1332支队伍参赛，涵盖高校、医疗机构、科技企业和科研院所。这场深度融合医保业务、医学影像、人工智能三大领域的专业赛事，正持续推动“人工智能+健康”创新发展。 国家医疗保障局大数据中心主任付超奇介绍，本次大赛设置8个赛道，覆盖肺癌、前列腺病变、乳腺癌等高发、疾病负担重且AI辅助诊断应用潜力突出的病种。 “获奖不是终点，而是把成果放进真实医疗体系的起点。”广西医…"
