    "description": "据知情人士透露，尽管中国科技企业需求旺盛，北京仍未批准大规模进口英伟达（Nvidia）先进人工智能晶片，约60万颗H200晶片目前存放在香港，等待被运往中国大陆。 路透社星期四（11月5日）引述知情人士报道，近几个月来，中国已允许部分晶片进入境内，数家中国大型互联网企业近几个月各获得了约1万枚H200晶片。 三名知情人士说，少量晶片已通过中间商及间接渠道运入中国，但没有说明具体数量。不过，北京据称仍未批准向中国大陆大规模进口H200晶片…",
    "content": "据知情人士透露，尽管中国科技企业需求旺盛，北京仍未批准大规模进口英伟达（Nvidia）先进人工智能晶片，约60万颗H200晶片目前存放在香港，等待被运往中国大陆。 路透社星期四（11月5日）引述知情人士报道，近几个月来，中国已允许部分晶片进入境内，数家中国大型互联网企业近几个月各获得了约1万枚H200晶片。 三名知情人士说，少量晶片已通过中间商及间接渠道运入中国，但没有说明具体数量。不过，北京据称仍未批准向中国大陆大规模进口H200晶片。 报道称，这批此前未被披露的H200晶片库存规模，反映出北京不愿进一步依赖美国…"
