    "content": "36氪获悉，杭电股份公告，公司董事长华建飞提议公司使用自有或自筹资金通过上海证券交易所交易系统以集中竞价交易方式回购公司已发行的部分人民币普通股（A股）股票，本次回购的股份拟用于员工股权激励/员工持股计划或减少公司注册资本。回购资金总额不低于5000万元（含），不超过1亿元（含）。回购价格不超过董事会通过回购股份决议前30个交易日公司股票交易均价的150%，具体以董事会审议通过的回购股份方案为准。"
