    "content": "新华社银川11月5日电 记者手记：黄河岸畔听“新声” 新华社记者张宋红、马丽娟 今年是人民治黄80周年。都说“天下黄河富宁夏”，记者沿黄河宁夏段踏访，岸畔声声汽笛、鸟啼、笑语，见证黄河保护治理成效，奏出新时代“黄河大合唱”塞上乐章。 一声笛鸣 绿带护安澜 “呜——”汽笛长鸣，一列货车缓缓驶出包兰铁路沙坡头车站，沿着黄河岸，钻进腾格里沙漠边缘。 中卫市沙坡头是宁夏防风阻沙的前沿。包兰铁路，新中国第一条沙漠铁路，在中卫段6次穿越腾格里沙漠，线路紧傍黄河。1958年建成通车后，它成为大河安澜长久的见证。 “那时候汽笛一响…"
