    "content": "新华社南宁11月5日电 新闻分析：稻香新村的足球赛事，为何非办不可？ 新华社记者朱丽莉 秋夜，广西桂平市石龙镇新村村的稻香足球场灯火通明。因洪涝损毁关闭数月的球场全新亮相，桂平市第二届“稻香杯”足球邀请赛焕新重启，赛事战火将燃至12月中旬。 一个以种植水稻为主的桂东南村庄，为何对办足球赛如此执着？在各类赛事增多的当下，乡村球赛究竟有何意义？新村村用坚持作答：办足球赛不是跟风逐流，而是乡村振兴的创新探索。 一块球场，带火一方乡村 新村村是水库移民村、水稻种植村，二十世纪七十年代开始，人们在此开荒、建渠、种稻、修屋。村…"
