    "content": "新华社东京11月5日电（记者李诗萌 蓝建中）日本丰田汽车公司5日发布最新财报显示，丰田本财年（2026年4月至2027年3月）净利润预计同比下降7.2%，至3.57万亿日元（1美元约合158日元）。 财报显示，丰田预计本财年营业额同比增长5.6%，达到53.5万亿日元；营业利润同比增长3.6%，达到3.9万亿日元。 该公司认为，中东局势和原材料价格上涨等因素将对本财年业绩产生影响。中东局势推高原油价格，人工智能需求旺盛导致半导体供应趋紧，相关采购成本也在上升。丰田财务相关负责人在当天举行的财报说明会上表示，日本和美…"
