    "content": "新华社索非亚11月5日电（记者姚雨璘）保加利亚总统选举最终结果3日公布，现年62岁的伊利亚娜·约托娃以约57.6%的得票率在第二轮投票中获胜，成为该国历史上首位民选女性国家元首。 11月1日，约托娃（中）在保加利亚首都索非亚接受媒体采访。新华社/美联 镜头前练就的“沟通者” 20世纪90年代，约托娃是保加利亚国家电视台的新闻主播，从记者、编辑一路做到新闻与时事节目总监。约托娃回忆说，电视直播“没有重来，没有预录”，这份工作教会她“对人坦诚”。 1997年，约托娃从新闻界转向政界，担任保加利亚社会党新闻处主任，随后于…"
