    "author": "",
    "description": "中新网上海11月5日电 (记者 许婧)当城市发展由大规模增量建设转向存量提质增效，科技创新如何更好赋能城市更新，开放合作又如何为全球城市治理注入新动能？4日，“第四届科技公共外交论坛暨2026世界城市日系列活动”在上海理工大学举行，来自科技创新、城市治理、生态环境、公共外交等领域的专家学者、企业代表和师生代表齐聚一堂，围绕“科创筑城联通世界”主题，共探城市可持续发展与国际合作的新路径。",
