    "content": "新华社吉隆坡11月5日电 专访｜期待世界媒体峰会推动交流互鉴和务实合作——访马来西亚国家新闻社主席黄振威 新华社记者袁睿 王嘉伟 马来西亚国家新闻社（马新社）主席黄振威日前在接受新华社记者专访时表示，在北京召开的第七届世界媒体峰会为各国新闻工作者提供了学习知识、交流经验、增进了解的重要平台。他期待峰会能够推动各方开展务实合作，为全球南方国家媒体发展提供更多助力。 黄振威说，人工智能快速发展，正为国际媒体合作开辟新的空间。马来西亚与中国交往频繁，能够从中国人工智能技术的发展中受益。他期待新华社、马新社等具有相关经验的…"
