    "author": "",
    "description": "36氪获悉，杰普特公告，拟以集中竞价交易方式回购公司股份，回购总金额不低于5000万元且不超过7000万元。回购价格不超过550元/股。回购股份将用于注销并减少注册资本。回购期限为自股东会审议通过回购方案之日起12个月内。",
