    "content": "日本首富、软银集团创始人兼CEO孙正义斥资近54亿美元吞并ABB机器人部门的计划受挫。 ABB集团官网11月5日发布的一则声明称，软银向其告知，中国外商投资安全审查工作机制办公室已禁止软银收购ABB在中国的机器人业务。“该交易需获得监管部门批准并满足惯例成交条件，监管部门审批流程由软银负责”，ABB称，双方正在密切沟通，并积极推进交易事宜。 2025年10月，双方宣布达成协议，ABB将旗下机器人业务部门出售给软银集团，交易企业价值为53.75亿美元。这是近年来全球工业自动化和机器人领域最重磅、也最引人注目的并购交易…"
