    "description": "美国总统 Donald Trump 出席白宫新宴会厅建造工程的最后一根钢梁吊装仪式，华盛顿特区。11月4日，美国总统 Trump 向媒体展示白宫新宴会厅的施工进展并在最后一根钢梁上签名留念，他称赞这座宴会厅不仅是规模最大的宴会厅，也将成为世界上最美丽的宴会厅。这是 Trump 在中期选举失利后首次公开露面，他在回答媒体提问时承认「伊朗战争」是导致共和党败选的一个主要因素，但是强调自己仍拥有对国会法案的否决权。最新计票结果显示民主党已赢得…",
    "content": "美国总统 Donald Trump 出席白宫新宴会厅建造工程的最后一根钢梁吊装仪式，华盛顿特区。11月4日，美国总统 Trump 向媒体展示白宫新宴会厅的施工进展并在最后一根钢梁上签名留念，他称赞这座宴会厅不仅是规模最大的宴会厅，也将成为世界上最美丽的宴会厅。这是 Trump 在中期选举失利后首次公开露面，他在回答媒体提问时承认「伊朗战争」是导致共和党败选的一个主要因素，但是强调自己仍拥有对国会法案的否决权。最新计票结果显示民主党已赢得240个众议院席位和54个参议院席位，同时控制参众两院的过半席位。摄影师：Man…"
