    "content": "快科技11月5日消息， 三星电子与东部高科最近签署约300台半导体制造设备转让合同，将器兴8英寸代工厂S7的半导体制造设备转让给东部高科。 此次设备出售源于三星电子退出8英寸代工业务。 三星电子今年年初决定关闭韩江三座8英寸工厂（S6、S7、S8）中的S7，并于9至10月停止其运营。 三星电子运营的8英寸晶圆代工涵盖65纳米、70纳米、90纳米、130纳米、180纳米等成熟制程，生产显示驱动芯片、电源管理芯片、微控制器、图像传感器等多种系统半导体。 三星电子于2000年启动180纳米工艺量产，此后于2002年、20…"
