    "content": "IT之家 11 月 5 日消息，法国地区性银行阿尔凯亚互助信贷银行（Crédit Mutuel Arkéa）周三表示，该行遭遇网络攻击，黑客通过此次攻击实施了欺诈性转账，涉案金额约为 1 亿欧元 （IT之家注：现汇率约合 7.5 亿元人民币） 。 该银行表示，此次攻击目前已得到控制。黑客入侵了阿尔凯亚银行自身的账户，并向其他银行账户转账，并未侵入客户账户，因此客户没有遭受任何资金损失。 阿尔凯亚银行补充称，被盗资金随后通过专业交易平台兑换成了加密货币。目前，部分资金已被冻结，银行也正在采取其他措施追回剩余资金。 该…"
