    "content": "新华社布鲁塞尔11月5日电 欧洲多家媒体5日报道，当天欧洲十余架客机遭炸弹威胁，其中部分客机已安全降落。 据法国媒体报道，一架从爱尔兰都柏林飞往意大利罗马的空客A320客机收到炸弹威胁警报，改道飞往法国，随后安全降落在埃夫勒空军基地。《法兰西西部报》援引涉事的爱尔兰航空公司消息报道说，机上共有151名乘客和6名机组人员，均已被转移至安全区域，排爆人员已抵达现场。 保加利亚交通部向当地媒体证实，当天上午3架飞往该国索非亚的瑞安航空公司航班遭炸弹威胁，其中从丹麦哥本哈根和西班牙马德里起飞的2架已抵达，另一架从伦敦起飞的…"
