    "content": "新华社东京11月5日电（记者李子越 陈泽安）日本共同社5日援引相关人士消息报道称，日本政府正考虑在计划于年底修订的《国家安全保障战略》中写入“无核三原则”例外情况，或允许在紧急情况下将核武器运进日本。 “无核三原则”指“不拥有、不制造、不运进核武器”。报道称，日本政府目前倾向于暂不直接修改“无核三原则”，而是以设定例外情况的方式允许在紧急情况下运进核武器。 这一方案主要参照日本前外务大臣冈田克也的国会答辩。2010年3月，冈田克也曾表示，如果发生紧急情况，若不允许搭载核武器的美军舰船临时停靠日本，就无法保障日本安全…"
