    "content": "新华社福州11月5日电 中共中央政治局委员、国务院副总理刘国中11月3日至5日到广西、福建调研。他强调，要深入学习贯彻党的二十届五中全会精神，贯彻落实习近平总书记在全国卫生与健康大会上的重要讲话精神，坚定不移走中国特色卫生与健康发展道路，贯彻新时代卫生与健康工作方针，推动卫生与健康事业高质量发展，确保“十五五”时期健康中国建设取得决定性进展，不断增进人民健康福祉。 刘国中先后来到广西柳州市、来宾市和福建福州市等地，深入乡镇卫生院和县级医院，召开座谈会，详细了解基层医疗卫生服务、县域医共体建设和运行等情况。他强调，要…"
