    "title": "钱怎么花，资产怎么守，路径怎么走：品牌出海的三道命题｜超级会氪厅嘉宾金句",
    "link": "https://36kr.com/p/4056464430847109?f=rss",
    "pub_date": "2026-11-05 18:02:54",
